@font-face {
  font-family: 'Inter';
  src: url('/fonts/Inter-Regular.woff2') format('woff2');
  font-weight: 400;
  font-style: normal;
  font-display: swap; /* Recommended for most content fonts */
}

@font-face {
  font-family: 'Open Sans';
  src: url('/fonts/OpenSans-Bold.woff2') format('woff2');
  font-weight: 700;
  font-style: normal;
  font-display: fallback; /* Offers a small block period then swaps */
}

/* For critical elements where a brief FOIT is acceptable to ensure correct icon rendering quickly */
@font-face {
  font-family: 'IconFont';
  src: url('/fonts/IconFont.woff2') format('woff2');
  font-weight: 400;
  font-style: normal;
  font-display: block; /* Blocks rendering for a short period until loaded */
}
